mapper.update:
update p_quota_balance set reserved_units = reserved_units - #{bytes}, used_units = used_units + #{bytes},
    revision = revision + 1, updated_at = utc_timestamp(3)
where account_id = #{accountId} and quota_type = 'STORAGE_BYTE' and reserved_units >= #{bytes}

update p_quota_balance set reserved_units = reserved_units - #{bytes}, revision = revision + 1,
    updated_at = utc_timestamp(3)
where account_id = #{accountId} and quota_type = 'STORAGE_BYTE' and reserved_units >= #{bytes}

update p_quota_balance set used_units = used_units - #{bytes}, revision = revision + 1,
    updated_at = utc_timestamp(3)
where account_id = #{accountId} and quota_type = 'STORAGE_BYTE' and used_units >= #{bytes}

update p_quota_reservation set state = 'SETTLED', settled_units = #{bytes},
    settled_at = utc_timestamp(3), updated_at = utc_timestamp(3)
where id = #{reservationId} and state = 'RESERVED' and reserved_units = #{bytes}

mapper.select:
select f.id fileId, f.account_id accountId, f.object_key objectKey, f.status
from p_file f where f.status in ('UPLOADING','DELETE_PENDING') and f.upload_expires_at < utc_timestamp(3)
order by f.upload_expires_at, f.id limit 100
